Dataspatium.assets.register("presets/api/ecb.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"ecb\",\n  \"name\": \"Europeiska centralbanken (ECB)\",\n  \"publisher\": \"Europeiska centralbanken\",\n  \"description\": \"Växelkurser, räntor, inflation och annan statistik från ECB:s Data Portal i formatet SDMX-JSON. Varje observation blir en rad med serienyckelns koder och namn, period och värde.\",\n  \"docs\": \"https://data.ecb.europa.eu/help/api/overview\",\n  \"license\": {\n    \"name\": \"Fri återanvändning med källangivelse (ECB)\",\n    \"url\": \"https://www.ecb.europa.eu/home/disclaimer/html/index.en.html\"\n  },\n  \"level\": 1,\n  \"country\": \"EU\",\n  \"baseUrl\": \"https://data-api.ecb.europa.eu/service/data\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"rateLimit\": {\n    \"requests\": 5,\n    \"perSeconds\": 1\n  },\n  \"endpoints\": [\n    {\n      \"id\": \"exchange\",\n      \"name\": \"Växelkurser mot euro\",\n      \"description\": \"ECB:s referenskurser, hur många enheter av valutan en euro kostar. Välj valutor och frekvens; medelkursen per period hämtas.\",\n      \"method\": \"GET\",\n      \"path\": \"/EXR/{freq}.{currency}.EUR.SP00.A\",\n      \"params\": [\n        {\n          \"name\": \"freq\",\n          \"in\": \"path\",\n          \"label\": \"Frekvens\",\n          \"type\": \"enum\",\n          \"default\": \"M\",\n          \"options\": [\n            {\n              \"value\": \"D\",\n              \"label\": \"Dag\"\n            },\n            {\n              \"value\": \"M\",\n              \"label\": \"Månad\"\n            },\n            {\n              \"value\": \"A\",\n              \"label\": \"År\"\n            }\n          ]\n        },\n        {\n          \"name\": \"currency\",\n          \"in\": \"path\",\n          \"label\": \"Valutor\",\n          \"type\": \"multi\",\n          \"join\": \"+\",\n          \"required\": true,\n          \"default\": \"SEK,NOK,DKK,ISK,USD\",\n          \"example\": \"SEK,NOK,DKK,ISK,USD\",\n          \"help\": \"ISO-koder åtskilda med kommatecken, till exempel SEK,NOK,USD.\"\n        },\n        {\n          \"name\": \"startPeriod\",\n          \"in\": \"query\",\n          \"label\": \"Från period\",\n          \"type\": \"string\",\n          \"example\": \"2020-01\"\n        },\n        {\n          \"name\": \"endPeriod\",\n          \"in\": \"query\",\n          \"label\": \"Till period\",\n          \"type\": \"string\"\n        },\n        {\n          \"name\": \"lastNObservations\",\n          \"in\": \"query\",\n          \"label\": \"Bara de senaste n observationerna\",\n          \"type\": \"number\"\n        },\n        {\n          \"name\": \"format\",\n          \"in\": \"query\",\n          \"type\": \"string\",\n          \"default\": \"jsondata\",\n          \"hidden\": true\n        }\n      ],\n      \"response\": {\n        \"format\": \"sdmx\"\n      },\n      \"dataset\": {\n        \"name\": \"ECB växelkurser {currency}\"\n      }\n    },\n    {\n      \"id\": \"data\",\n      \"name\": \"Hämta serier (SDMX)\",\n      \"description\": \"Valfritt dataflöde och serienyckel från ECB Data Portal. Exempel: FM med B.U2.EUR.4F.KR.MRR_FR.LEV ger styrräntan, ICP med M.SE+DK+FI.N.000000.4.ANR inflationen. Nycklar hittar du på data.ecb.europa.eu.\",\n      \"method\": \"GET\",\n      \"path\": \"/{flow}/{key}\",\n      \"params\": [\n        {\n          \"name\": \"flow\",\n          \"in\": \"path\",\n          \"label\": \"Dataflöde\",\n          \"type\": \"string\",\n          \"required\": true,\n          \"example\": \"ICP\"\n        },\n        {\n          \"name\": \"key\",\n          \"in\": \"path\",\n          \"label\": \"Serienyckel\",\n          \"type\": \"string\",\n          \"required\": true,\n          \"raw\": true,\n          \"example\": \"M.SE+DK+FI.N.000000.4.ANR\",\n          \"help\": \"Dimensionernas koder åtskilda med punkt; + väljer flera koder och en tom position alla.\"\n        },\n        {\n          \"name\": \"startPeriod\",\n          \"in\": \"query\",\n          \"label\": \"Från period\",\n          \"type\": \"string\",\n          \"example\": \"2020-01\"\n        },\n        {\n          \"name\": \"endPeriod\",\n          \"in\": \"query\",\n          \"label\": \"Till period\",\n          \"type\": \"string\"\n        },\n        {\n          \"name\": \"lastNObservations\",\n          \"in\": \"query\",\n          \"label\": \"Bara de senaste n observationerna\",\n          \"type\": \"number\"\n        },\n        {\n          \"name\": \"format\",\n          \"in\": \"query\",\n          \"type\": \"string\",\n          \"default\": \"jsondata\",\n          \"hidden\": true\n        }\n      ],\n      \"response\": {\n        \"format\": \"sdmx\"\n      },\n      \"dataset\": {\n        \"name\": \"ECB {flow} {key}\"\n      }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"European Central Bank (ECB)\",\n      \"publisher\": \"European Central Bank\",\n      \"description\": \"Exchange rates, interest rates, inflation and other statistics from the ECB Data Portal in the SDMX-JSON format. Every observation becomes a row with the codes and names of the series key, the period and the value.\",\n      \"endpoints\": {\n        \"exchange\": {\n          \"name\": \"Exchange rates against the euro\",\n          \"description\": \"The ECB reference rates: how many units of the currency one euro costs. Choose currencies and frequency; the average rate per period is fetched.\",\n          \"params\": {\n            \"freq\": {\n              \"label\": \"Frequency\",\n              \"options\": {\n                \"D\": \"Day\",\n                \"M\": \"Month\",\n                \"A\": \"Year\"\n              }\n            },\n            \"currency\": {\n              \"label\": \"Currencies\",\n              \"help\": \"ISO codes separated by commas, for example SEK,NOK,USD.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"From period\"\n            },\n            \"endPeriod\": {\n              \"label\": \"To period\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Only the latest n observations\"\n            }\n          }\n        },\n        \"data\": {\n          \"name\": \"Fetch series (SDMX)\",\n          \"description\": \"Any dataflow and series key from the ECB Data Portal. Examples: FM with B.U2.EUR.4F.KR.MRR_FR.LEV gives the main refinancing rate, ICP with M.SE+DK+FI.N.000000.4.ANR inflation. Keys are found on data.ecb.europa.eu.\",\n          \"params\": {\n            \"flow\": {\n              \"label\": \"Dataflow\"\n            },\n            \"key\": {\n              \"label\": \"Series key\",\n              \"help\": \"The codes of the dimensions separated by full stops; + chooses several codes and an empty position all of them.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"From period\"\n            },\n            \"endPeriod\": {\n              \"label\": \"To period\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Only the latest n observations\"\n            }\n          }\n        }\n      },\n      \"dataset\": {\n        \"exchange\": \"ECB exchange rates {currency}\",\n        \"data\": \"ECB {flow} {key}\"\n      }\n    },\n    \"da\": {\n      \"name\": \"Den Europæiske Centralbank (ECB)\",\n      \"publisher\": \"Den Europæiske Centralbank\",\n      \"description\": \"Valutakurser, renter, inflation og anden statistik fra ECB's Data Portal i formatet SDMX-JSON. Hver observation bliver en række med seriens koder og navne, periode og værdi.\",\n      \"endpoints\": {\n        \"exchange\": {\n          \"name\": \"Valutakurser over for euro\",\n          \"description\": \"ECB's referencekurser: hvor mange enheder af valutaen en euro koster. Vælg valutaer og frekvens; gennemsnitskursen pr. periode hentes.\",\n          \"params\": {\n            \"freq\": {\n              \"label\": \"Frekvens\",\n              \"options\": {\n                \"D\": \"Dag\",\n                \"M\": \"Måned\",\n                \"A\": \"År\"\n              }\n            },\n            \"currency\": {\n              \"label\": \"Valutaer\",\n              \"help\": \"ISO-koder adskilt med kommaer, for eksempel DKK,NOK,USD.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Fra periode\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til periode\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Kun de seneste n observationer\"\n            }\n          }\n        },\n        \"data\": {\n          \"name\": \"Hent serier (SDMX)\",\n          \"description\": \"Vilkårligt dataflow og serienøgle fra ECB Data Portal. Eksempler: FM med B.U2.EUR.4F.KR.MRR_FR.LEV giver styringsrenten, ICP med M.SE+DK+FI.N.000000.4.ANR inflationen. Nøgler findes på data.ecb.europa.eu.\",\n          \"params\": {\n            \"flow\": {\n              \"label\": \"Dataflow\"\n            },\n            \"key\": {\n              \"label\": \"Serienøgle\",\n              \"help\": \"Dimensionernes koder adskilt med punktum; + vælger flere koder og en tom position dem alle.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Fra periode\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til periode\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Kun de seneste n observationer\"\n            }\n          }\n        }\n      },\n      \"dataset\": {\n        \"exchange\": \"ECB valutakurser {currency}\",\n        \"data\": \"ECB {flow} {key}\"\n      }\n    },\n    \"nb\": {\n      \"name\": \"Den europeiske sentralbanken (ECB)\",\n      \"publisher\": \"Den europeiske sentralbanken\",\n      \"description\": \"Valutakurser, renter, inflasjon og annen statistikk fra ECBs Data Portal i formatet SDMX-JSON. Hver observasjon blir en rad med seriens koder og navn, periode og verdi.\",\n      \"endpoints\": {\n        \"exchange\": {\n          \"name\": \"Valutakurser mot euro\",\n          \"description\": \"ECBs referansekurser: hvor mange enheter av valutaen en euro koster. Velg valutaer og frekvens; gjennomsnittskursen per periode hentes.\",\n          \"params\": {\n            \"freq\": {\n              \"label\": \"Frekvens\",\n              \"options\": {\n                \"D\": \"Dag\",\n                \"M\": \"Måned\",\n                \"A\": \"År\"\n              }\n            },\n            \"currency\": {\n              \"label\": \"Valutaer\",\n              \"help\": \"ISO-koder skilt med komma, for eksempel NOK,SEK,USD.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Fra periode\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til periode\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Bare de siste n observasjonene\"\n            }\n          }\n        },\n        \"data\": {\n          \"name\": \"Hent serier (SDMX)\",\n          \"description\": \"Valgfri dataflyt og serienøkkel fra ECB Data Portal. Eksempler: FM med B.U2.EUR.4F.KR.MRR_FR.LEV gir styringsrenten, ICP med M.SE+DK+FI.N.000000.4.ANR inflasjonen. Nøkler finner du på data.ecb.europa.eu.\",\n          \"params\": {\n            \"flow\": {\n              \"label\": \"Dataflyt\"\n            },\n            \"key\": {\n              \"label\": \"Serienøkkel\",\n              \"help\": \"Dimensjonenes koder skilt med punktum; + velger flere koder og en tom posisjon alle.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Fra periode\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til periode\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Bare de siste n observasjonene\"\n            }\n          }\n        }\n      },\n      \"dataset\": {\n        \"exchange\": \"ECB valutakurser {currency}\",\n        \"data\": \"ECB {flow} {key}\"\n      }\n    },\n    \"fi\": {\n      \"name\": \"Euroopan keskuspankki (EKP)\",\n      \"publisher\": \"Euroopan keskuspankki\",\n      \"description\": \"Valuuttakurssit, korot, inflaatio ja muut tilastot EKP:n Data Portalista SDMX-JSON-muodossa. Jokaisesta havainnosta tulee rivi, jossa ovat sarja-avaimen koodit ja nimet, ajanjakso ja arvo.\",\n      \"endpoints\": {\n        \"exchange\": {\n          \"name\": \"Valuuttakurssit euroa vastaan\",\n          \"description\": \"EKP:n viitekurssit: montako valuutan yksikköä euro maksaa. Valitse valuutat ja tiheys; kauden keskikurssi haetaan.\",\n          \"params\": {\n            \"freq\": {\n              \"label\": \"Tiheys\",\n              \"options\": {\n                \"D\": \"Päivä\",\n                \"M\": \"Kuukausi\",\n                \"A\": \"Vuosi\"\n              }\n            },\n            \"currency\": {\n              \"label\": \"Valuutat\",\n              \"help\": \"ISO-koodit pilkuin erotettuina, esimerkiksi SEK,NOK,USD.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Alkaen\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Päättyen\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Vain n viimeisintä havaintoa\"\n            }\n          }\n        },\n        \"data\": {\n          \"name\": \"Hae sarjoja (SDMX)\",\n          \"description\": \"Mikä tahansa EKP:n Data Portalin tietovirta ja sarja-avain. Esimerkkejä: FM ja B.U2.EUR.4F.KR.MRR_FR.LEV antaa ohjauskoron, ICP ja M.SE+DK+FI.N.000000.4.ANR inflaation. Avaimet löytyvät osoitteesta data.ecb.europa.eu.\",\n          \"params\": {\n            \"flow\": {\n              \"label\": \"Tietovirta\"\n            },\n            \"key\": {\n              \"label\": \"Sarja-avain\",\n              \"help\": \"Ulottuvuuksien koodit pisteillä erotettuina; + valitsee useita koodeja ja tyhjä kohta kaikki.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Alkaen\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Päättyen\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Vain n viimeisintä havaintoa\"\n            }\n          }\n        }\n      },\n      \"dataset\": {\n        \"exchange\": \"EKP valuuttakurssit {currency}\",\n        \"data\": \"EKP {flow} {key}\"\n      }\n    },\n    \"is\": {\n      \"name\": \"Seðlabanki Evrópu (ECB)\",\n      \"publisher\": \"Seðlabanki Evrópu\",\n      \"description\": \"Gengi, vextir, verðbólga og önnur tölfræði úr Data Portal ECB á SDMX-JSON-sniði. Hver athugun verður að röð með kóðum og heitum raðlykilsins, tímabili og gildi.\",\n      \"endpoints\": {\n        \"exchange\": {\n          \"name\": \"Gengi gagnvart evru\",\n          \"description\": \"Viðmiðunargengi ECB: hve margar einingar gjaldmiðilsins ein evra kostar. Veldu gjaldmiðla og tíðni; meðalgengi hvers tímabils er sótt.\",\n          \"params\": {\n            \"freq\": {\n              \"label\": \"Tíðni\",\n              \"options\": {\n                \"D\": \"Dagur\",\n                \"M\": \"Mánuður\",\n                \"A\": \"Ár\"\n              }\n            },\n            \"currency\": {\n              \"label\": \"Gjaldmiðlar\",\n              \"help\": \"ISO-kóðar aðgreindir með kommum, til dæmis ISK,SEK,USD.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Frá tímabili\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til tímabils\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Aðeins n nýjustu athuganirnar\"\n            }\n          }\n        },\n        \"data\": {\n          \"name\": \"Sækja raðir (SDMX)\",\n          \"description\": \"Hvaða gagnaflæði og raðlykill sem er úr Data Portal ECB. Dæmi: FM með B.U2.EUR.4F.KR.MRR_FR.LEV gefur stýrivexti, ICP með M.SE+DK+FI.N.000000.4.ANR verðbólgu. Lykla má finna á data.ecb.europa.eu.\",\n          \"params\": {\n            \"flow\": {\n              \"label\": \"Gagnaflæði\"\n            },\n            \"key\": {\n              \"label\": \"Raðlykill\",\n              \"help\": \"Kóðar víddanna aðgreindir með punktum; + velur marga kóða og auð staða alla.\"\n            },\n            \"startPeriod\": {\n              \"label\": \"Frá tímabili\"\n            },\n            \"endPeriod\": {\n              \"label\": \"Til tímabils\"\n            },\n            \"lastNObservations\": {\n              \"label\": \"Aðeins n nýjustu athuganirnar\"\n            }\n          }\n        }\n      },\n      \"dataset\": {\n        \"exchange\": \"Gengi ECB {currency}\",\n        \"data\": \"ECB {flow} {key}\"\n      }\n    }\n  }\n}\n");
